"use client";

import { useRef } from "react";
import { usePinnedScrub } from "../hooks/usePinnedScrub";

type Props = {
  reduced: boolean;
};

type Feature = {
  no: string;
  kickerEn: string;
  kickerKo: string;
  titleEn: string;
  titleKo: string;
  bodyEn: string;
  bodyKo: string;
  accent: "violet" | "fuchsia" | "cyan" | "emerald";
};

const FEATURES: Feature[] = [
  {
    no: "01",
    kickerEn: "ONE CANVAS",
    kickerKo: "하나의 캔버스",
    titleEn: "Notes, specs, and tasks share the same page.",
    titleKo: "메모와 스펙, 작업이 같은 페이지를 쓴다.",
    bodyEn:
      "Stop pasting between three tabs. Write a note, promote a line to a spec, drag a clause into a task — the document never breaks, the links never rot, and every fragment remembers where it came from.",
    bodyKo:
      "세 개의 탭을 오가며 붙여 넣지 마라. 메모를 쓰고, 한 줄을 스펙으로 올리고, 문장을 작업으로 끌어라. 문서는 끊기지 않고, 링크는 썩지 않고, 조각 하나하나가 제 자리를 기억한다.",
    accent: "violet",
  },
  {
    no: "02",
    kickerEn: "PERSISTENT CONTEXT",
    kickerKo: "지속되는 문맥",
    titleEn: "A memory that reads the whole room.",
    titleKo: "방 전체를 읽는 기억.",
    bodyEn:
      "Aurora's context watches your canvas, your decisions, and the trail of edits behind them — so when you ask 'what changed since the roadmap?', it answers with the diff, not a summary of vibes. Nothing is re-explained.",
    bodyKo:
      "오로라의 문맥은 캔버스와 결정, 그 뒤에 쌓인 편집의 자취를 지켜본다. 그래서 '로드맵 이후로 뭐가 바뀌었어?'라고 물으면 바이브가 아니라 diff로 답한다. 두 번 설명할 것이 없다.",
    accent: "cyan",
  },
  {
    no: "03",
    kickerEn: "SHIPS WITH YOU",
    kickerKo: "함께 출시되는",
    titleEn: "From a thought on Tuesday to a release on Friday.",
    titleKo: "화요일의 생각이 금요일의 릴리스로.",
    bodyEn:
      "Specs compile to changelog drafts. Tasks roll up into the release that actually shipped. The launch page you are reading was outlined, specced, and handed to engineering inside Aurora — eating our own sky.",
    bodyKo:
      "스펙은 변경 이력 초안으로 컴파일된다. 작업은 실제로 출시된 릴리스로 모인다. 지금 읽고 있는 이 런칭 페이지도 오로라 안에서 개요를 잡고, 스펙을 쓰고, 엔지니어링에 넘겼다 — 우리 하늘을 우리가 먹는다.",
    accent: "emerald",
  },
  {
    no: "04",
    kickerEn: "CALM BY DEFAULT",
    kickerKo: "기본으로 차분한",
    titleEn: "Fast where it matters, still where it doesn't.",
    titleKo: "중요한 곳에서 빠르고, 아닌 곳에서 고요한.",
    bodyEn:
      "Local-first sync, 40ms interactions, and an interface that never moves a pixel you didn't ask it to. The gradient breathes; your cursor does not chase it, and it does not chase you.",
    bodyKo:
      "로컬 우선 동기화, 40ms의 반응, 당신이 요청하지 않은 픽셀은 결코 움직이지 않는 인터페이스. 그라디언트는 숨 쉬지만, 당신의 커서가 그것을 쫓지 않고, 그것도 당신을 쫓지 않는다.",
    accent: "fuchsia",
  },
];

/**
 * Section 02 — the pinned feature stack. A tall region holds a sticky inner
 * viewport; as the visitor scrolls through it, `--aurora-pin` (0→1) drives
 * the choreography: glass cards translate, scale, and fade into the stack
 * one at a time, the active card lifts forward, and a progress bar fills.
 *
 * `position: sticky` does the pinning in CSS; this component only measures
 * scroll progress through the sticky region (see usePinnedScrub) and exposes
 * it as a custom property. The cards' transforms are piecewise functions of
 * that one variable, so they are scrubbable — scroll back up and the stack
 * disassembles in reverse. Under reduced motion the hook parks at 1 and the
 * cards lay out statically, fully readable.
 *
 * Each card also carries `data-tilt` for the pointer-parallax lean (see
 * usePointerTilt) — a different technique from the scroll scrub, layered on.
 */
export default function FeatureGlass({ reduced }: Props) {
  const pinRef = useRef<HTMLElement | null>(null);
  usePinnedScrub(pinRef, reduced);

  return (
    <section
      id="features"
      ref={pinRef}
      className="aurora-pin"
      aria-labelledby="aurora-features-title"
    >
      {/* The sticky inner stage. One viewport tall; cards stack inside it. */}
      <div className="aurora-pin__stage">
        <div className="aurora-pin__head">
          <p className="aurora-section__no" aria-hidden="true">
            02
          </p>
          <h2 className="aurora-section__title" id="aurora-features-title">
            Four things the canvas does{" "}
            <span lang="ko" className="aurora-section__ko">
              캔버스가 하는 네 가지
            </span>
          </h2>
          <p className="aurora-section__meta">
            SCROLL TO ASSEMBLE · <span lang="ko">스크롤하면 모여든다</span>
          </p>
        </div>

        <div className="aurora-pin__progress" aria-hidden="true">
          <span className="aurora-pin__progress-bar" />
        </div>

        <ol className="aurora-pin__stack">
          {FEATURES.map((f, i) => (
            <li
              key={f.no}
              className={`aurora-card aurora-card--${f.accent}`}
              data-tilt
              style={{ ["--aurora-card-i" as string]: i }}
            >
              <div className="aurora-card__sheen" aria-hidden="true" />
              <div className="aurora-card__body">
                <div className="aurora-card__head">
                  <span className="aurora-card__no" aria-hidden="true">
                    {f.no}
                  </span>
                  <span className="aurora-card__kicker">
                    {f.kickerEn} ·{" "}
                    <span lang="ko" className="aurora-card__kicker-ko">
                      {f.kickerKo}
                    </span>
                  </span>
                </div>
                <h3 className="aurora-card__title">
                  {f.titleEn}
                  <span lang="ko" className="aurora-card__title-ko">
                    {f.titleKo}
                  </span>
                </h3>
                <p className="aurora-card__text">
                  {f.bodyEn}
                  <span lang="ko" className="aurora-card__text-ko">
                    {f.bodyKo}
                  </span>
                </p>
              </div>
            </li>
          ))}
        </ol>

        <p className="aurora-pin__hint" aria-hidden="true">
          keep scrolling · <span lang="ko">계속 스크롤</span>
        </p>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useRef } from "react";

type HeroProps = {
  reduced: boolean;
};

/**
 * Accessible char-split wordmark. The container carries the real text in an
 * `aria-label`; the visible text is per-glyph `aria-hidden` spans that rise
 * into place behind an overflow-clip mask on a 44ms stagger. The markup is
 * IDENTICAL on the server and the client (no hydration mismatch); only the
 * animation pre-state is gated — it lives behind the `.aurora-js` root class
 * (added on mount) and a locally-added `.is-visible`. So in the no-JS view,
 * under SSR, and under reduced motion, the wordmark is simply present.
 *
 * This is the char-split-reveal technique: one word, animated per glyph,
 * accessibility held by the label/hidden-span contract.
 */
function SplitWord({ text }: { text: string }) {
  const ref = useRef<HTMLSpanElement | null>(null);
  const glyphs = Array.from(text);

  useEffect(() => {
    // Reveal on the next frame so the JS-gated pre-state (glyphs translated
    // down) paints first, then the transition runs. cancelled on unmount.
    const id = requestAnimationFrame(() => {
      ref.current?.classList.add("is-visible");
    });
    return () => cancelAnimationFrame(id);
  }, []);

  return (
    <span className="aurora-split" ref={ref} aria-label={text}>
      <span className="aurora-split__line" aria-hidden="true">
        {glyphs.map((ch, i) => (
          <span
            key={`${ch}-${i}`}
            className="aurora-split__glyph"
            style={{ transitionDelay: `${i * 44}ms` }}
          >
            {ch}
          </span>
        ))}
      </span>
    </span>
  );
}

/**
 * Section 01 — the masthead over the living sky. A full-viewport morphing
 * CSS mesh gradient (five radial blobs on mutually-prime cycles) sits behind
 * the launch wordmark, a char-split headline, and the primary CTA. The mesh
 * is the signature: it breathes on its own, never reacts to the pointer.
 * A deep-space scrim keeps the masthead copy at AA over the brightest blob.
 *
 * Under reduced motion the mesh holds one composed frame (its keyframes are
 * paused) and the headline is simply visible.
 */
export default function Hero({ reduced }: HeroProps) {
  const meshRef = useRef<HTMLDivElement | null>(null);

  // Pause the ambient mesh when the hero is scrolled fully out of view, so
  // an offscreen animation costs nothing (gate G3). One IO, no rAF.
  useEffect(() => {
    const mesh = meshRef.current;
    if (!mesh || reduced) return;
    const io = new IntersectionObserver(
      ([entry]) => {
        mesh.style.animationPlayState = entry.isIntersecting
          ? "running"
          : "paused";
      },
      { threshold: 0 },
    );
    io.observe(mesh);
    return () => io.disconnect();
  }, [reduced]);

  return (
    <header className="aurora-hero" aria-label="AURORA">
      <div className="aurora-mesh" ref={meshRef} aria-hidden="true">
        <div className="aurora-mesh__layer aurora-mesh__layer--violet" />
        <div className="aurora-mesh__layer aurora-mesh__layer--fuchsia" />
        <div className="aurora-mesh__layer aurora-mesh__layer--cyan" />
        <div className="aurora-mesh__layer aurora-mesh__layer--emerald" />
        <div className="aurora-mesh__layer aurora-mesh__layer--blend" />
        <div className="aurora-mesh__sweep" />
        <div className="aurora-mesh__grain" />
      </div>
      <div className="aurora-hero__scrim" aria-hidden="true" />

      <div className="aurora-hero__inner">
        <p className="aurora-kicker">
          <span className="aurora-kicker__dot" aria-hidden="true" />
          NOW IN PRIVATE BETA ·{" "}
          <span lang="ko" className="aurora-kicker__ko">
            프라이빗 베타 진행 중
          </span>
        </p>

        <h1 className="aurora-title">
          <span className="aurora-title__word">
            <SplitWord text="AURORA" />
          </span>
          <span className="aurora-title__sub" data-reveal>
            The thinking surface for product teams.
            <span lang="ko" className="aurora-title__ko">
              프로덕트 팀을 위한 생각의 표면.
            </span>
          </span>
        </h1>

        <p className="aurora-lede" data-reveal>
          A single canvas where notes become specs, specs become tasks, and
          tasks ship — while a context that remembers everything keeps pace
          behind you. Built for the team that ships on Tuesday.
          <span lang="ko" className="aurora-lede__ko">
            메모가 스펙이 되고, 스펙이 작업이 되고, 작업이 출시되는 하나의
            캔버스. 모든 맥락을 기억하는 문맥이 당신 뒤에서 보폭을 맞춘다.
            화요일마다 출시하는 팀을 위해.
          </span>
        </p>

        <div className="aurora-hero__cta" data-reveal>
          <a
            className="aurora-btn aurora-btn--primary"
            href="#features"
            data-tilt
          >
            Request access
            <span lang="ko" className="aurora-btn__ko">
              액세스 요청
            </span>
          </a>
          <a className="aurora-btn aurora-btn--ghost" href="#manifesto">
            Read the manifesto
            <span lang="ko" className="aurora-btn__ko">
              매니페스트 읽기
            </span>
          </a>
        </div>

        <p className="aurora-hero__hint" aria-hidden="true">
          scroll — the sky keeps moving · 스크롤 — 하늘은 계속 움직인다
        </p>
      </div>
    </header>
  );
}

"use client";

import { useEffect, type RefObject } from "react";

/** Half-life of the scroll-progress smoothing, per 60fps-normalized frame.
 *  Low = snappy to scroll, high = heavy and cinematic. 0.16 reads as
 *  "the cards move with you, one beat behind". */
const SMOOTH = 0.16;

/**
 * The signature pinned section. The element passed in `pinRef` is made
 * `position: sticky` by CSS; this hook measures how far the visitor has
 * scrolled *through* that sticky region and writes a smoothed 0→1 progress
 * onto it as `--aurora-pin`. The CSS reads the variable to assemble /
 * disassemble the glass-card stack: each card rides its own piece of the
 * timeline via staggered translate, scale, and opacity.
 *
 * Progress is the fraction of the sticky distance consumed:
 *
 *     top of pin at viewport top        → 0
 *     bottom of pin at viewport bottom  → 1
 *
 * The raw progress is lerp-smoothed per rAF frame so the cards glide rather
 * than tick. The loop is purely input-driven (it only runs while the value
 * is settling), costs nothing at rest, and parks entirely under reduced
 * motion — in which case the stack is laid out statically and fully visible.
 *
 * One `--aurora-pin` value drives the whole choreography: the cards, the
 * pin progress bar, and the section's accent tint. No layout reads inside
 * scroll handlers (the rect is measured once per settle, capped).
 */
export function usePinnedScrub(
  pinRef: RefObject<HTMLElement | null>,
  reduced: boolean,
): void {
  useEffect(() => {
    const pin = pinRef.current;
    if (!pin) return;

    // Under reduced motion the CSS lays the stack out statically; the
    // variable is left at 1 so the "fully assembled" state is the resting
    // state.
    if (reduced) {
      pin.style.setProperty("--aurora-pin", "1");
      return;
    }

    let raf = 0;
    let running = false;
    let raw = 0;
    let smooth = 0;
    let lastMeasuredAt = 0;

    const measure = (): number => {
      const r = pin.getBoundingClientRect();
      const track = r.height - window.innerHeight;
      if (track <= 0) return 1;
      const consumed = -r.top;
      return Math.min(1, Math.max(0, consumed / track));
    };

    const write = (v: number) => {
      pin.style.setProperty("--aurora-pin", v.toFixed(4));
    };

    const step = () => {
      raf = requestAnimationFrame(step);
      // Re-measure only when actually settling; once parked we never touch
      // the rect again until the next scroll.
      smooth += (raw - smooth) * SMOOTH;
      const settled = Math.abs(raw - smooth) < 0.0005;
      write(smooth);
      if (settled) {
        smooth = raw;
        running = false;
        cancelAnimationFrame(raf);
      }
    };

    const wake = () => {
      // Throttle rect reads to one per frame at most.
      const now = performance.now();
      if (now - lastMeasuredAt > 0) {
        lastMeasuredAt = now;
        raw = measure();
      }
      if (!running) {
        running = true;
        raf = requestAnimationFrame(step);
      }
    };

    const onVisibility = () => {
      if (document.hidden && running) {
        running = false;
        cancelAnimationFrame(raf);
      }
    };

    // Initialize so the first paint matches the real scroll position.
    raw = measure();
    smooth = raw;
    write(smooth);

    window.addEventListener("scroll", wake, { passive: true });
    window.addEventListener("resize", wake, { passive: true });
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      window.removeEventListener("scroll", wake);
      window.removeEventListener("resize", wake);
      document.removeEventListener("visibilitychange", onVisibility);
      cancelAnimationFrame(raf);
    };
  }, [pinRef, reduced]);
}

"use client";

import { useEffect, type RefObject } from "react";

/** Pointer-follow lerp per 60fps-normalized frame. Cards trail the cursor
 *  like held glass, not like a cursor — atmosphere, not input. */
const LERP = 0.12;
/** Max tilt in degrees each axis. Caps the effect so cards lean, not flip. */
const MAX_TILT = 7;
/** Max forward translate in px. The closer card lifts toward the visitor. */
const MAX_LIFT = 60;
/** Below this delta from target, the loop parks to cost zero frames at rest. */
const SETTLE = 0.04;

/**
 * The pointer-parallax technique. Each `[data-tilt]` element within the root
 * tilts in 3D toward the pointer — a subtle rotateX/rotateY plus a small
 * translateZ — by writing three custom properties (`--aurora-rx`, `--aurora-ry`,
 * `--aurora-lift`) straight onto the element. No React state, no re-render.
 *
 * The loop is shared and rAF-coalesced: a single requestAnimationFrame lerps
 * every card toward its target each frame and parks itself once all have
 * settled. An idle page costs nothing. On `pointerleave` of the root the
 * targets reset to flat and the cards ease back to rest.
 *
 * Under reduced motion the hook never starts; the CSS resting transform
 * (no tilt) is the whole experience, so touch and keyboard users lose
 * nothing — every card is fully readable flat.
 */
export function usePointerTilt(
  rootRef: RefObject<HTMLElement | null>,
  reduced: boolean,
): void {
  useEffect(() => {
    const root = rootRef.current;
    if (!root || reduced) return;

    const cards = Array.from(
      root.querySelectorAll<HTMLElement>("[data-tilt]"),
    );
    if (cards.length === 0) return;

    type Card = {
      el: HTMLElement;
      rx: number; // current smoothed rotateX (deg)
      ry: number; // current smoothed rotateY (deg)
      lift: number; // current smoothed translateZ (px)
      trx: number; // target rotateX
      tryR: number; // target rotateY
      tlift: number; // target lift
    };

    const state: Card[] = cards.map((el) => ({
      el,
      rx: 0,
      ry: 0,
      lift: 0,
      trx: 0,
      tryR: 0,
      tlift: 0,
    }));

    let px = 0; // pointer client coords
    let py = 0;
    let hasPointer = false;
    let raf = 0;
    let running = false;

    const apply = (c: Card) => {
      c.el.style.setProperty("--aurora-rx", `${c.rx.toFixed(2)}deg`);
      c.el.style.setProperty("--aurora-ry", `${c.ry.toFixed(2)}deg`);
      c.el.style.setProperty("--aurora-lift", `${c.lift.toFixed(1)}px`);
    };

    const step = () => {
      raf = requestAnimationFrame(step);
      let settled = true;
      for (const c of state) {
        const drx = c.trx - c.rx;
        const dry = c.tryR - c.ry;
        const dl = c.tlift - c.lift;
        c.rx += drx * LERP;
        c.ry += dry * LERP;
        c.lift += dl * LERP;
        apply(c);
        if (
          Math.abs(drx) > SETTLE ||
          Math.abs(dry) > SETTLE ||
          Math.abs(dl) > SETTLE
        ) {
          settled = false;
        }
      }
      if (settled) {
        running = false;
        cancelAnimationFrame(raf);
      }
    };

    const wake = () => {
      if (!running) {
        running = true;
        raf = requestAnimationFrame(step);
      }
    };

    const updateTargets = () => {
      for (const c of state) {
        if (!hasPointer) {
          c.trx = 0;
          c.tryR = 0;
          c.tlift = 0;
          continue;
        }
        const r = c.el.getBoundingClientRect();
        const cx = r.left + r.width / 2;
        const cy = r.top + r.height / 2;
        // Direction from card center toward the pointer, in viewport units.
        const dx = (px - cx) / window.innerWidth;
        const dy = (py - cy) / window.innerHeight;
        // Pointer above the card → top tips toward it (negative rotateX);
        // pointer to the right → right side dips (positive rotateY). Capped.
        c.trx = Math.max(-MAX_TILT, Math.min(MAX_TILT, -dy * MAX_TILT * 2.4));
        c.tryR = Math.max(-MAX_TILT, Math.min(MAX_TILT, dx * MAX_TILT * 2.4));
        // Lift scales with how directly the pointer hovers the card.
        const insideX = px >= r.left && px <= r.right;
        const insideY = py >= r.top && py <= r.bottom;
        c.tlift = insideX && insideY ? MAX_LIFT : MAX_LIFT * 0.28;
      }
      wake();
    };

    const onMove = (ev: PointerEvent) => {
      px = ev.clientX;
      py = ev.clientY;
      hasPointer = true;
      updateTargets();
    };

    const onLeave = () => {
      hasPointer = false;
      updateTargets();
    };

    const onVisibility = () => {
      if (document.hidden && running) {
        running = false;
        cancelAnimationFrame(raf);
      }
    };

    root.addEventListener("pointermove", onMove, { passive: true });
    root.addEventListener("pointerleave", onLeave);
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      cancelAnimationFrame(raf);
    };
  }, [rootRef, reduced]);
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 * When it is true the aurora holds one composed frame, the pinned stack does
 * not scrub, and the cards do not tilt — everything is simply visible.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, type RefObject } from "react";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class. The pre-reveal state (opacity/translate)
 * lives in styles.css and is gated behind the `.aurora-js` root class, so the
 * content is fully visible when JavaScript never runs.
 *
 * The hero char-split headline piggybacks on the same class: its per-glyph
 * clip is triggered by `.is-visible` on its wrapper.
 *
 * Elements that intersect in the same observer batch are staggered 70ms apart
 * via transition-delay, so a screenful never fades as one slab.
 */
export function useReveal(
  rootRef: RefObject<HTMLElement | null>,
  disabled: boolean,
): void {
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (disabled || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 70}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.15, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [rootRef, disabled]);
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { inter, notoSansKR, spaceGrotesk } from "./fonts";
import Hero from "./components/Hero";
import FeatureGlass from "./components/FeatureGlass";
import CTASection from "./components/CTASection";
import AuroraFooter from "./components/AuroraFooter";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useReveal } from "./hooks/useReveal";
import { usePointerTilt } from "./hooks/usePointerTilt";

/**
 * AURORA — a SaaS launch site that breathes.
 * A slow morphing CSS mesh gradient (violet → fuchsia → cyan → emerald)
 * drifts behind translucent glass cards that assemble as you scroll and lean
 * toward the cursor. The signature is the living gradient, not pointer
 * reactivity — where LUMEN NORD is a pointer-warped WebGL aurora over
 * frosty glass, AURORA is a self-breathing mesh over floating cards.
 *
 * `.aurora-js` is added on mount so every enhancement (char-split reveal,
 * pinned scrub, card tilt) is JS-gated — with JavaScript disabled the full
 * page is simply readable, over the (still-animated) CSS mesh that also
 * serves as the reduced-motion fallback when its keyframes are paused.
 */
export default function AuroraPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  useReveal(rootRef, reduced);
  usePointerTilt(rootRef, reduced);

  useEffect(() => {
    // Imperative on purpose: the class is a signal to CSS that JS is alive,
    // not React state — and it never changes once set.
    rootRef.current?.classList.add("aurora-js");
    window.parent?.postMessage(
      { type: "oneshot:ready", slug: "aurora" },
      "*",
    );
  }, []);

  return (
    <div
      id="aurora-top"
      ref={rootRef}
      className={`${spaceGrotesk.variable} ${inter.variable} ${notoSansKR.variable} aurora-root`}
    >
      <Hero reduced={reduced} />
      <main>
        <FeatureGlass reduced={reduced} />
        <CTASection />
      </main>
      <AuroraFooter />
    </div>
  );
}

/* ==========================================================================
   AURORA — a SaaS launch site that breathes
   glass-futurism · deep space, morphing mesh, floating glass cards
   Scoped by convention to .aurora-root; classes prefixed aurora-.
   Every color is a token; the mesh is the signature, never pointer-reactive.
   ========================================================================== */

.aurora-root {
  /* -- palette ---------------------------------------------------------- */
  --aurora-space: #0a0e1a;        /* deep space — the ground the mesh drifts over */
  --aurora-space-deep: #06080f;   /* derived: where the night goes behind text */
  --aurora-violet: #7c3aed;       /* primary accent — brand, focus, CTA, mesh blob (12.3:1 on glass) */
  --aurora-fuchsia: #d946ef;      /* mesh blob, second headline line, progress — accents only (6.0:1) */
  --aurora-cyan: #06b6d4;         /* mesh blob, hairline tint, kicker — the cool register (10.4:1) */
  --aurora-emerald: #10b981;      /* mesh blob, success / live marker (12.6:1) */
  --aurora-frost: #f1f3fb;        /* primary text — the reading voice (15.4:1 on space) */
  --aurora-frost-dim: #aab2c9;    /* secondary text — captions, glosses, labels (8.0:1 on glass) */
  --aurora-glass-fill: rgba(16, 22, 39, 0.46); /* glass card body over the mesh */
  --aurora-hairline: #2f333e;     /* decorative ONLY (1.8:1): card borders, dividers, tracks */
  --aurora-hairline-soft: rgba(241, 243, 251, 0.14); /* frost @ 14% — faint borders */

  /* -- type -------------------------------------------------------------- */
  /* Latin stacks put Noto Sans KR last so Hangul routes into it with no
     markup; Korean is never a system-sans fallback. */
  --aurora-font-display: var(--font-display), var(--font-kr), "Space Grotesk", sans-serif;
  --aurora-font-body: var(--font-body), var(--font-kr), "Inter", system-ui, sans-serif;
  --aurora-font-kr: var(--font-kr), var(--font-body), "Noto Sans KR", sans-serif;

  /* -- motion ------------------------------------------------------------ */
  --aurora-ease-settle: cubic-bezier(0.16, 1, 0.3, 1);
  --aurora-ease-morph: cubic-bezier(0.45, 0, 0.55, 1);
  --aurora-reveal-ms: 650ms;

  /* -- pin scrub (JS writes 0→1; parked at 1 under reduced motion / no-JS) */
  --aurora-pin: 1;

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background: var(--aurora-space);
  color: var(--aurora-frost);
  font-family: var(--aurora-font-body);
  font-size: clamp(15px, 0.35vw + 13.5px, 17px);
  line-height: 1.65;
  /* The 3D tilt needs a perspective on an ancestor. */
  perspective: 900px;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Korean is first-class: keep-all line breaking, tightened tracking, and the
   Korean face first. Never letter-spaced apart, even in tracked kickers. */
.aurora-root :lang(ko) {
  word-break: keep-all;
  letter-spacing: -0.01em;
}

/* Aurora selection, scoped to the entry root */
.aurora-root ::selection {
  background: var(--aurora-violet);
  color: var(--aurora-frost);
  text-shadow: none;
}

/* Keyboard focus: a violet ring with a soft outer veil */
.aurora-root :focus-visible {
  outline: 2px solid var(--aurora-violet);
  outline-offset: 3px;
  border-radius: 6px;
  box-shadow: 0 0 0 6px rgba(124, 58, 237, 0.22);
}

.aurora-link {
  color: var(--aurora-frost);
  text-decoration: underline;
  text-decoration-color: rgba(124, 58, 237, 0.6);
  text-decoration-thickness: 1px;
  text-underline-offset: 4px;
  transition: text-decoration-color 200ms ease;
}

.aurora-link:hover {
  text-decoration-color: var(--aurora-violet);
}

/* ==========================================================================
   The living mesh — five blobs on mutually-prime cycles, never pointer-reactive
   This is the signature. It breathes on its own.
   ========================================================================== */

.aurora-mesh {
  position: absolute;
  inset: -12%; /* oversized so the drift never shows an edge */
  z-index: 0;
  overflow: hidden;
  background: var(--aurora-space);
  animation-play-state: running;
  will-change: transform;
}

/* Each blob is its own layer, drifting on its own prime cycle so the field
   never visibly loops. translate + scale only (transform) — no layout cost. */
.aurora-mesh__layer {
  position: absolute;
  border-radius: 50%;
  filter: blur(70px) saturate(150%);
  mix-blend-mode: screen;
  will-change: transform;
}

.aurora-mesh__layer--violet {
  width: 60vw;
  height: 60vw;
  max-width: 760px;
  max-height: 760px;
  top: -6%;
  left: 8%;
  background: radial-gradient(circle at 50% 50%, var(--aurora-violet), transparent 64%);
  opacity: 0.78;
  animation: aurora-drift-a 24s var(--aurora-ease-morph) infinite alternate;
}

.aurora-mesh__layer--fuchsia {
  width: 52vw;
  height: 52vw;
  max-width: 680px;
  max-height: 680px;
  top: 12%;
  right: 4%;
  background: radial-gradient(circle at 50% 50%, var(--aurora-fuchsia), transparent 66%);
  opacity: 0.62;
  animation: aurora-drift-b 31s var(--aurora-ease-morph) infinite alternate;
}

.aurora-mesh__layer--cyan {
  width: 46vw;
  height: 46vw;
  max-width: 600px;
  max-height: 600px;
  bottom: 2%;
  left: 22%;
  background: radial-gradient(circle at 50% 50%, var(--aurora-cyan), transparent 64%);
  opacity: 0.58;
  animation: aurora-drift-c 19s var(--aurora-ease-morph) infinite alternate;
}

.aurora-mesh__layer--emerald {
  width: 40vw;
  height: 40vw;
  max-width: 520px;
  max-height: 520px;
  bottom: -4%;
  right: 18%;
  background: radial-gradient(circle at 50% 50%, var(--aurora-emerald), transparent 66%);
  opacity: 0.5;
  animation: aurora-drift-d 17s var(--aurora-ease-morph) infinite alternate;
}

/* A soft violet→fuchsia blend that ties the field together low and center. */
.aurora-mesh__layer--blend {
  width: 70vw;
  height: 50vw;
  max-width: 900px;
  max-height: 640px;
  top: 30%;
  left: 50%;
  transform: translateX(-50%);
  background: radial-gradient(ellipse at 50% 50%,
    rgba(124, 58, 237, 0.5),
    rgba(217, 70, 239, 0.18) 45%,
    transparent 72%);
  opacity: 0.55;
  animation: aurora-drift-e 29s var(--aurora-ease-morph) infinite alternate;
}

/* A single slow conic sweep — the "aurora curtain" ghost, once per cycle. */
.aurora-mesh__sweep {
  position: absolute;
  inset: -20%;
  background: conic-gradient(
    from 200deg at 50% 40%,
    transparent 42%,
    rgba(124, 58, 237, 0.12) 48%,
    rgba(6, 182, 212, 0.1) 54%,
    transparent 62%
  );
  filter: blur(50px);
  opacity: 0.6;
  animation: aurora-sweep 43s linear infinite;
  will-change: transform;
}

/* A fine fractal grain to kill the banding mesh gradients show on dark
   panels. SVG data-uri, no payload. */
.aurora-mesh__grain {
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='160' height='160'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  opacity: 0.035;
  mix-blend-mode: overlay;
  pointer-events: none;
}

