/* -- the glass card primitive ------------------------------------------- */
.aurora-card {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  /* pointer-tilt vars (JS-written; flat by default) */
  --aurora-rx: 0deg;
  --aurora-ry: 0deg;
  --aurora-lift: 0px;
  /* Each card's piece of the timeline: card i enters in the slice
     [i/N .. (i+1)/N] of --aurora-pin. */
  --aurora-card-i: 0;
  /* stash the count locally for the calc */
  --aurora-card-n: 4;
  transform:
    translateY(calc(var(--aurora-card-offset, 0px)))
    scale(var(--aurora-card-scale, 1))
    translateZ(var(--aurora-lift))
    rotateX(var(--aurora-rx))
    rotateY(var(--aurora-ry));
  transform-style: preserve-3d;
  border: 1px solid var(--aurora-hairline-soft);
  border-radius: 22px;
  background:
    linear-gradient(150deg, rgba(241, 243, 251, 0.07), rgba(241, 243, 251, 0) 42%),
    var(--aurora-glass-fill);
  -webkit-backdrop-filter: blur(18px) saturate(160%);
  backdrop-filter: blur(18px) saturate(160%);
  box-shadow:
    inset 0 1px 0 rgba(241, 243, 251, 0.18),
    0 24px 60px rgba(4, 6, 16, 0.55);
  opacity: var(--aurora-card-opacity, 1);
  overflow: hidden;
  transition: transform 120ms linear; /* tilt is rAF-driven; this smooths edges */
  will-change: transform, opacity;
}

