/* ==========================================================================
   02b · The scrub choreography
   --aurora-pin is 0..1. Card i's local progress p_i:
     p_i = clamp((pin - i/n) / (1/n), 0, 1)
   Before its slice: hidden below + transparent. In its slice: rises to 0,
   scale 1, opaque. After its slice (overtopped by the next card): recedes —
   slight upward drift, scale down, dimmed — the "assembling/disassembling"
   read. The LAST card never recedes.
   These are pure functions of the custom property, so fully scrubbable.
   ========================================================================== */

/* For each card, derive p_i. calc() with custom props handles it inline. */
.aurora-card {
  /* p_i in [0,1]: how far through THIS card's slice the scroll is */
  --aurora-pi: clamp(
    0,
    calc(
      (var(--aurora-pin) - var(--aurora-card-i) / var(--aurora-card-n))
      * var(--aurora-card-n)
    ),
    1
  );
  /* entered = 1 once p_i > 0, i.e. pin past the card's start; 0 before. */
  --aurora-entered: clamp(0, calc(var(--aurora-pi) * 9999), 1);
  /* overtaken = 1 once the NEXT card has started entering; 0 until then.
     Last card (i = n-1) is never overtaken. */
  --aurora-overtaken: clamp(
    0,
    calc(
      (var(--aurora-pi) - (1 - 1 / var(--aurora-card-n) + 0.001))
      * 9999
    ),
    1
  );
  /* On the last card, force overtaken to 0. (i == n-1 check via clamp.) */
  --aurora-is-last: clamp(0, calc((var(--aurora-card-i) - (var(--aurora-card-n) - 1.5)) * 9999), 1);

  /* The visible state: rise from below + fade in on enter; */
  --aurora-card-offset: calc((1 - var(--aurora-entered)) * 90px + var(--aurora-overtaken-final) * -28px);
  --aurora-card-scale: calc(1 - var(--aurora-overtaken-final) * 0.06);
  --aurora-card-opacity: calc(var(--aurora-entered) * (1 - var(--aurora-overtaken-final) * 0.5));
}

/* overtaken-final: 0 for the last card, otherwise the raw overtaken value.
   (We multiply overtaken by (1 - is-last) — but calc can't branch, so we
   subtract: overtaken * (1 - is_last).) */
.aurora-card {
  --aurora-overtaken-final: calc(var(--aurora-overtaken) * (1 - var(--aurora-is-last)));
}

/* ==========================================================================
   03 · CTA / manifesto
   ========================================================================== */

.aurora-cta {
  position: relative;
  padding: clamp(90px, 14vh, 170px) clamp(20px, 5vw, 64px);
}

.aurora-cta__inner {
  position: relative;
  z-index: 1;
  max-width: 880px;
  margin-inline: auto;
}

.aurora-cta__title {
  margin: 0.4rem 0 0;
  font-family: var(--aurora-font-display);
  font-weight: 600;
  font-size: clamp(1.7rem, 3.8vw, 2.8rem);
  line-height: 1.2;
  letter-spacing: -0.015em;
  max-width: 20ch;
}

.aurora-cta__title-ko {
  display: block;
  font-family: var(--aurora-font-kr);
  font-weight: 500;
  font-size: 0.62em;
  line-height: 1.4;
  color: var(--aurora-frost-dim);
  margin-top: 0.4em;
}

.aurora-cta__body {
  margin: clamp(1.4rem, 3vh, 2.2rem) 0 0;
  max-width: 62ch;
  font-size: clamp(1.02rem, 1.5vw, 1.2rem);
  line-height: 1.65;
}

.aurora-cta__body-ko {
  display: block;
  font-family: var(--aurora-font-kr);
  margin-top: 0.6rem;
  color: var(--aurora-frost-dim);
  line-height: 1.75;
}

.aurora-cta__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.4rem;
  margin: clamp(2rem, 4.5vh, 3rem) 0 0;
}

.aurora-cta__note {
  font-size: 0.85rem;
  color: var(--aurora-frost-dim);
  max-width: 36ch;
}

.aurora-cta__log {
  margin: clamp(2.6rem, 6vh, 4rem) 0 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1px;
  background: var(--aurora-hairline);
  border: 1px solid var(--aurora-hairline);
  border-radius: 14px;
  overflow: hidden;
}

.aurora-cta__log div {
  background: rgba(10, 14, 26, 0.72);
  padding: 1.1rem 1.2rem;
}

.aurora-cta__log dt {
  margin: 0 0 0.4rem;
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--aurora-frost-dim);
}

.aurora-cta__log dd {
  margin: 0;
  font-family: var(--aurora-font-display);
  font-weight: 600;
  font-size: 1.05rem;
  color: var(--aurora-frost);
}

/* ==========================================================================
   04 · Footer — end of launch
   ========================================================================== */

.aurora-footer {
  max-width: 1020px;
  margin-inline: auto;
  padding: clamp(64px, 10vh, 120px) clamp(20px, 5vw, 64px)
    clamp(90px, 13vh, 150px);
  border-top: 1px solid var(--aurora-hairline);
}

.aurora-footer__signoff {
  margin: 0 0 2.2rem;
  font-family: var(--aurora-font-display);
  font-weight: 600;
  font-size: clamp(1.3rem, 2.6vw, 1.9rem);
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.aurora-footer__ko {
  display: block;
  font-family: var(--aurora-font-kr);
  font-weight: 500;
  font-size: 0.72em;
  color: var(--aurora-frost-dim);
  margin-top: 0.4em;
}

.aurora-footer__data {
  margin: 0 0 2.4rem;
}

.aurora-footer__data div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.2rem 1.2rem;
  padding: 0.55rem 0;
  border-bottom: 1px dotted var(--aurora-hairline);
}

.aurora-footer__data dt {
  flex: 0 0 7rem;
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--aurora-frost-dim);
  line-height: 2.1;
}

.aurora-footer__data dd {
  flex: 1 1 16rem;
  margin: 0;
}

.aurora-footer__live {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--aurora-emerald);
  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.22);
  vertical-align: middle;
  margin-right: 0.4em;
}

.aurora-footer__nav {
  margin: 0 0 2.4rem;
  font-size: 0.9rem;
}

.aurora-footer__copy {
  margin: 0;
  font-size: 0.9rem;
  color: var(--aurora-frost-dim);
}

.aurora-footer__copy .aurora-footer__ko {
  display: inline;
  margin-left: 0.4em;
}

/* ==========================================================================
   Scroll reveals — JS-gated pre-state, transform/opacity only
   ========================================================================== */

.aurora-js [data-reveal] {
  opacity: 0;
  transform: translateY(16px);
  transition:
    opacity var(--aurora-reveal-ms) var(--aurora-ease-settle),
    transform var(--aurora-reveal-ms) var(--aurora-ease-settle);
  will-change: opacity, transform;
}

.aurora-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ==========================================================================
   Keyframes — transform only; the mesh breathes on mutually-prime cycles
   ========================================================================== */

@keyframes aurora-drift-a {
  0%   { transform: translate3d(-4%, 2%, 0) scale(1.02) rotate(-2deg); }
  100% { transform: translate3d(6%, -3%, 0) scale(1.14) rotate(3deg); }
}

@keyframes aurora-drift-b {
  0%   { transform: translate3d(3%, -2%, 0) scale(1.08) rotate(2deg); }
  100% { transform: translate3d(-5%, 4%, 0) scale(0.96) rotate(-3deg); }
}

@keyframes aurora-drift-c {
  0%   { transform: translate3d(-2%, 4%, 0) scale(1.05); }
  100% { transform: translate3d(4%, -3%, 0) scale(1.16); }
}

@keyframes aurora-drift-d {
  0%   { transform: translate3d(4%, -2%, 0) scale(1.1) rotate(1.5deg); }
  100% { transform: translate3d(-3%, 3%, 0) scale(1) rotate(-2deg); }
}

@keyframes aurora-drift-e {
  0%   { transform: translateX(-50%) translate3d(-3%, 0, 0) scale(1.05); }
  100% { transform: translateX(-50%) translate3d(3%, 2%, 0) scale(1.12); }
}

@keyframes aurora-sweep {
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* ==========================================================================
   Reduced motion — one composed still, everything readable
   The mesh keyframes pause on a mid-pose; the pin parks at 1 (fully
   assembled); reveals and char-split are simply visible.
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .aurora-mesh,
  .aurora-mesh__layer,
  .aurora-mesh__sweep {
    animation: none !important;
    /* Hold a composed mid-pose so the field still reads as a living sky,
       frozen at one beautiful frame. */
    transform: none;
  }
  .aurora-mesh__layer--blend {
    transform: translateX(-50%);
  }

  .aurora-card {
    transition: none;
  }

  .aurora-btn {
    transition: none;
  }

  .aurora-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  /* The pinned stack lays out statically and fully readable. We turn the
     absolute stack into a normal vertical list so all four cards are
     visible without scrubbing. */
  .aurora-pin {
    height: auto;
  }
  .aurora-pin__stage {
    position: static;
    height: auto;
  }
  .aurora-pin__stack {
    height: auto;
    display: flex;
    flex-direction: column;
    gap: 1.2rem;
  }
  .aurora-card {
    position: relative;
    inset: auto;
    --aurora-card-offset: 0px;
    --aurora-card-scale: 1;
    --aurora-card-opacity: 1;
    transform: none;
  }
  .aurora-pin__progress-bar {
    transform: scaleX(1);
  }
}

/* ==========================================================================
   Responsive — composed at 360px and 1440px+
   ========================================================================== */

@media (max-width: 600px) {
  .aurora-title__word {
    font-size: clamp(2.8rem, 16vw, 5rem);
  }
  .aurora-card__body {
    padding: clamp(20px, 6vw, 28px);
  }
  .aurora-card__head {
    flex-wrap: wrap;
    gap: 0.4rem 0.8rem;
  }
  .aurora-pin__stack {
    height: clamp(380px, 60vh, 540px);
  }
}

@media (min-width: 1440px) {
  .aurora-hero__inner,
  .aurora-pin__stage,
  .aurora-cta__inner {
    max-width: 1280px;
  }
}
